import{_ as l,a0 as r,w as o,s as d,I as n,x as e,a1 as i,A as p,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在免费 WiFi 中保护隐私（二） | LCTT x X-CMD","titleTemplate":false,"description":"如何在免费 WiFi 中保护隐私（二） | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在免费 WiFi 中保护隐私（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在免费 WiFi 中保护隐私（二） | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210804 Install OpenVPN on your Linux PC","title":"如何在免费 WiFi 中保护隐私（二）","tag":"202108","desc":""},"relativePath":"202108/20210804 Install OpenVPN on your Linux PC.md","filePath":"[post].md"}'),u={name:"202108/20210804 Install OpenVPN on your Linux PC.md"};function h(g,s,k,b,c,f){const a=r("Link");return o(),d("div",null,[s[30]||(s[30]=n("h1",{id:"如何在免费-wifi-中保护隐私-二",tabindex:"-1"},[e("如何在免费 WiFi 中保护隐私（二） "),n("a",{class:"header-anchor",href:"#如何在免费-wifi-中保护隐私-二","aria-label":"Permalink to “如何在免费 WiFi 中保护隐私（二）”"},"​")],-1)),s[31]||(s[31]=n("blockquote",null,[n("p",null,"安装完服务器之后，下一步就是安装和配置 0penVPN。")],-1)),s[32]||(s[32]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/20/123417yn554549p92ujt54.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=e("0penVPN 在两点之间创建一个加密通道，阻止第三方访问你的网络流量数据。通过设置你的 “虚拟专用网络” 服务，你可以成为你自己的 “虚拟专用网络” 服务商。许多流行的 “虚拟专用网络” 服务都使用 ",-1)),i(a,{href:"https://openvpn.net/"},{default:p(()=>[...s[0]||(s[0]=[e("0penVPN",-1)])]),_:1}),s[2]||(s[2]=e("，所以当你可以掌控自己的网络时，为什么还要将你的网络连接绑定到特定的提供商呢？",-1))]),n("p",null,[s[4]||(s[4]=e("本系列的 ",-1)),i(a,{href:"https://linux.cn/article-13680-1.html"},{default:p(()=>[...s[3]||(s[3]=[e("第一篇文章",-1)])]),_:1}),s[5]||(s[5]=e(" 展示了如何安装和配置一台作为你的 0penVPN 服务器的 Linux 计算机。同时也讲述了如何配置你的路由器以便你可以在外部网络连接到你的服务器。",-1))]),n("p",null,[s[7]||(s[7]=e("第二篇文章将演示根据 ",-1)),i(a,{href:"https://community.openvpn.net/openvpn/wiki"},{default:p(()=>[...s[6]||(s[6]=[e("0penVPN wiki",-1)])]),_:1}),s[8]||(s[8]=e(" 给定的步骤安装一个 0penVPN 服务软件。",-1))]),s[33]||(s[33]=t(`<h3 id="安装-0penvpn" tabindex="-1">安装 0penVPN <a class="header-anchor" href="#安装-0penvpn" aria-label="Permalink to “安装 0penVPN”">​</a></h3><p>首先，使用包管理器安装 0penVPN 和 <code>easy-rsa</code> 应用程序（帮助你在服务器上设置身份验证）。本例使用的是 Fedora Linux，如果你选择了不同的发行版，请选用合适的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install openvpn easy-rsa</span></span></code></pre></div><p>此操作会创建一些空目录：</p><ul><li><code>/etc/openvpn</code></li><li><code>/etc/openvpn/client</code></li><li><code>/etc/openvpn/server</code></li></ul><p>如果这些目录在安装的过程中没有创建，请手动创建它们。</p><h3 id="设置身份验证" tabindex="-1">设置身份验证 <a class="header-anchor" href="#设置身份验证" aria-label="Permalink to “设置身份验证”">​</a></h3><p>0penVPN 依赖于 <code>easy-rsa</code> 脚本，并且应该有自己的副本。复制 <code>easy-rsa</code> 脚本和文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /etc/openvpn/easy-rsa</span></span>
<span class="line"><span>$ sudo cp -rai /usr/share/easy-rsa/3/* /etc/openvpn/easy-rsa/</span></span></code></pre></div><p>身份验证很重要，0penVPN 非常重视它。身份验证的理论是，如果 Alice 需要访问 Bob 公司内部的私人信息，那么 Bob 确保 Alice 真的是 Alice 就至关重要。同样的，Alice 也必须确保 Bob 是真正的 Bob。我们称之为相互认证。</p><p>现有的最佳实践是从三个可能因素中的选择两个检查属性：</p><ul><li>你拥有的</li><li>你知道的</li><li>你是谁</li></ul><p>选择有很多。0penVPN 安装使用如下：</p><ul><li><strong>证书</strong>：客户端和服务端都拥有的东西</li><li><strong>证书口令</strong>：某人知道的东西</li></ul><p>Alice 和 Bob 需要帮助彼此来验证身份。由于他们都相信 Cathy，Cathy 承担了称为 <ruby>证书颁发机构<rt>certificate authority</rt></ruby>（CA）的角色。Cathy 证明 Alice 和 Bob 都是他们自己。因为 Alice 和 Bob 都信任 Cathy，现在他们也相互信任了。</p><p>但是是什么让 Cathy 相信 Alice 和 Bob 是真的 Alice 和 Bob？Cathy 在社区的声誉取决于如何正确处理这件事，因此如果她希望 Denielle、Evan、Fiona、Greg 和其他人也信任她，她就需要严格测试 Alice 和 Bob 的宣称内容。当 Alice 和 Bob 向 Cathy 证明了他们是真的 Alice 和 Bob 之后，Cathy 将向 Alice 和 Bob 签署证书，让他们彼此和全世界分享。</p><p>Alice 和 Bob 如何知道是 Cathy 签署了证书，而不是某个人冒充她签发了证书？他们使用一项叫做<strong>公钥加密</strong>的技术：</p><ul><li>找到一种用一个密钥加密并用另一个密钥解密的加密算法。</li><li>将其中一个设为私钥，将另外一个设为公钥。</li><li>Cathy 与全世界分享她的公钥和她的签名的明文副本。</li><li>Cathy 用她的私钥加密她的签名，任何人都可以用她分享的公钥解密。</li><li>如果 Cathy 的签名解密后与明文副本匹配，Alice 和 Bob 就可以相信 Cathy 确实签署了它。</li></ul><p>每次在线购买商品和服务时，使用的就是这种技术。</p><h3 id="认证实现" tabindex="-1">认证实现 <a class="header-anchor" href="#认证实现" aria-label="Permalink to “认证实现”">​</a></h3>`,20)),n("p",null,[s[10]||(s[10]=e("0penVPN 的 ",-1)),i(a,{href:"https://openvpn.net/community-resources/"},{default:p(()=>[...s[9]||(s[9]=[e("文档",-1)])]),_:1}),s[11]||(s[11]=e(" 建议在单独的系统上或者至少在 0penVPN 服务器的单独目录上设置 CA。该文档还建议分别从服务端和客户端生成各自的证书。因为这是一个简单的演示设置，你可以使用 0penVPN 服务器设置 CA，并将证书和密钥放入服务器上的指定目录中。",-1))]),s[34]||(s[34]=t(`<p>从服务端生成证书，并将证书拷贝到各个客户端，避免客户端再次设置。</p><p>此实现使用自签名证书。这是因为服务器信任自己，而客户端信任服务器。因此，服务器是签署证书的最佳 CA。</p><p>在 0penVPN 服务器上设置 CA：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /etc/openvpn/ca</span></span>
<span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa init-pki</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa build-ca</span></span></code></pre></div><p>使用一个易记难猜的密码。</p><p>设置服务器密钥对和认证请求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/server</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa init-pki</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa gen-req OVPNserver2020 nopass</span></span></code></pre></div><p>在此例中，<code>OVPNServer2020</code> 是你在本系列第一篇文章中为 0penVPN 服务器设置的主机名。</p><h3 id="生成和签署证书" tabindex="-1">生成和签署证书 <a class="header-anchor" href="#生成和签署证书" aria-label="Permalink to “生成和签署证书”">​</a></h3><p>现在你必须向 CA 发送服务器请求并生成和签署服务器证书。</p><p>此步骤实质上是将请求文件从 <code>/etc/openvpn/server/pki/reqs/OVPNserver2020.req</code> 复制到 <code>/etc/openvpn/ca/pki/reqs/OVPNserver2020.req</code> 以准备审查和签名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  import-req /etc/openvpn/server/pki/reqs/OVPNserver2020.req OVPNserver2020</span></span></code></pre></div><h3 id="审查并签署请求" tabindex="-1">审查并签署请求 <a class="header-anchor" href="#审查并签署请求" aria-label="Permalink to “审查并签署请求”">​</a></h3><p>你已经生成了一个请求，所以现在你必须审查并签署证书：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  show-req OVPNserver2020</span></span></code></pre></div><p>以服务器身份签署请求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  sign-req server OVPNserver2020</span></span></code></pre></div><p>将服务器和 CA 证书的副本放在它们所属的位置，以便配置文件获取它们：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp /etc/openvpn/ca/pki/issued/OVPNserver2020.crt \\</span></span>
<span class="line"><span>  /etc/openvpn/server/pki/</span></span>
<span class="line"><span>$ sudo cp /etc/openvpn/ca/pki/ca.crt \\</span></span>
<span class="line"><span>  /etc/openvpn/server/pki/</span></span></code></pre></div>`,19)),n("p",null,[s[13]||(s[13]=e("接下来，生成 ",-1)),i(a,{href:"https://en.wikipedia.org/wiki/Diffie%E2%80%93Hellman_key_exchange"},{default:p(()=>[...s[12]||(s[12]=[e("Diffie-Hellman",-1)])]),_:1}),s[14]||(s[14]=e(" 参数，以便客户端和服务器可以交换会话密钥：",-1))]),s[35]||(s[35]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/server</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa gen-dh</span></span></code></pre></div><h3 id="快完成了" tabindex="-1">快完成了 <a class="header-anchor" href="#快完成了" aria-label="Permalink to “快完成了”">​</a></h3><p>本系列的下一篇文章将演示如何配置和启动你刚刚构建的 0penVPN 服务器。</p><p>本文的部分内容改编自 D. Greg Scott 的博客，并经许可重新发布。</p><hr>`,5)),n("p",null,[s[16]||(s[16]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/21/7/openvpn-router"},{default:p(()=>[...s[15]||(s[15]=[e("https://opensource.com/article/21/7/openvpn-router",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/greg-scott"},{default:p(()=>[...s[17]||(s[17]=[e("D. Greg Scott",-1)])]),_:1}),s[22]||(s[22]=e(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[18]||(s[18]=[e("lujun9972",-1)])]),_:1}),s[23]||(s[23]=e(" 译者：",-1)),i(a,{href:"https://github.com/perfiffer"},{default:p(()=>[...s[19]||(s[19]=[e("perfiffer",-1)])]),_:1}),s[24]||(s[24]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[20]||(s[20]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[27]||(s[27]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[25]||(s[25]=[e("LCTT",-1)])]),_:1}),s[28]||(s[28]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:p(()=>[...s[26]||(s[26]=[e("Linux中国",-1)])]),_:1}),s[29]||(s[29]=e(" 荣誉推出",-1))])])}const m=l(u,[["render",h]]);export{C as __pageData,m as default};
